/**
 * The policy half of `sync.ts`: every value `settings.ts` compares exactly,
 * written into the consumer's `.claude/settings.json`, `bunfig.toml` and
 * `package.json`'s `deps` script, so a
 * harness change to a hook or a list lands with the pin rather than as a hand
 * edit in each consumer. What the check only refuses — an empty allow list,
 * `disableAllHooks`, an `mcp__` deny or allow rule with parentheses — stays
 * the consumer's to fix, since no harness change can introduce it.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { HOOKS, MARK, registration } from "./bootstrap.ts";
import { isRecord } from "./is-record.ts";
import {
	ASK,
	ATTRIBUTION,
	DENY,
	DEPS,
	EDIT_ASK,
	EDIT_DENY,
	INSTALL,
	MARKETPLACE,
	MCP_ASK,
	PLUGINS,
} from "./settings.ts";

type Group = { matcher?: string; hooks?: { command?: unknown }[] };
type Settings = {
	permissions?: { deny?: string[]; ask?: string[] };
	hooks?: Record<string, Group[]>;
	attribution?: unknown;
	enabledPlugins?: Record<string, unknown>;
	extraKnownMarketplaces?: Record<string, unknown>;
};

/**
 * Whether the harness wrote `command`: it ends with `MARK`, or it is a
 * current hook's text without it, as consumers copied it by hand before the
 * mark existed. A project hook calling a harness script by its path is
 * neither, so it survives.
 */
const ours = (command: unknown) =>
	typeof command === "string" &&
	(command.endsWith(MARK) || HOOKS.some((hook) => hook.command === `${command} ${MARK}`));

const read = (file: string) => (existsSync(file) ? readFileSync(file, "utf8") : undefined);

/**
 * `list` with its entries starting with `prefix` replaced by `entries`, where
 * the first of them stood, or after the rest when there is none. The check
 * compares each such subset whole — `Bash(` in both lists, `mcp__` in `ask` —
 * so the harness owns all of it; every other entry keeps its place.
 */
function owned(list: string[], prefix: string, entries: string[]) {
	const first = list.findIndex((entry) => entry.startsWith(prefix));
	const rest = list.filter((entry) => !entry.startsWith(prefix));
	const at = first === -1 ? rest.length : first;
	return [...rest.slice(0, at), ...entries, ...rest.slice(at)];
}

/** `list` with `file` appended when absent. */
const withFile = (list: string[], file: string) => (list.includes(file) ? list : [...list, file]);

/** `text` parsed by `parse`, `{}` for a missing file, or a throw naming `file`. */
function parsed(file: string, text: string | undefined, parse: (text: string) => unknown = JSON.parse) {
	try {
		return text === undefined ? {} : parse(text);
	} catch (error) {
		throw new Error(`${file}: ${(error as Error).message}`);
	}
}

/** The indentation `text` uses, a tab where it shows none. */
const indentOf = (text: string | undefined) => text?.match(/\n([ \t]+)"/)?.[1] ?? "\t";

/**
 * The settings file's new text: the harness's hooks, lists, attribution, two
 * plugins and `ponytail` marketplace, the rest kept.
 */
function settingsText(text: string | undefined): string {
	const config = parsed(".claude/settings.json", text) as Settings;
	const hooks = config.hooks ?? {};
	for (const [event, groups] of Object.entries(hooks)) {
		if (!Array.isArray(groups)) throw new Error(`.claude/settings.json: hooks.${event} is not a list`);
		hooks[event] = groups.flatMap((group) => {
			if (typeof group !== "object" || group === null)
				throw new Error(`.claude/settings.json: an entry of hooks.${event} is not an object`);
			if (group.hooks === undefined) return [group];
			if (!Array.isArray(group.hooks))
				throw new Error(`.claude/settings.json: a hooks list under hooks.${event} is not a list`);
			const kept = group.hooks.filter((hook) => !ours(hook?.command));
			return kept.length ? [{ ...group, hooks: kept }] : [];
		});
	}
	for (const hook of HOOKS) {
		const groups = hooks[hook.event] ?? [];
		groups.push({ ...(hook.matcher === undefined ? {} : { matcher: hook.matcher }), hooks: [registration(hook)] });
		hooks[hook.event] = groups;
	}
	// An event whose only hooks were a previous version's, and which the
	// harness no longer registers, would otherwise be left as an empty list.
	for (const [event, groups] of Object.entries(hooks)) if (groups.length === 0) delete hooks[event];
	config.hooks = hooks;
	const permissions = config.permissions ?? {};
	permissions.deny = withFile(owned(permissions.deny ?? [], "Bash(", DENY), EDIT_DENY);
	permissions.ask = owned(withFile(owned(permissions.ask ?? [], "Bash(", ASK), EDIT_ASK), "mcp__", MCP_ASK);
	config.permissions = permissions;
	config.attribution = ATTRIBUTION;
	// Spread, a list or a string would lose the consumer's own entries without a word.
	for (const key of ["enabledPlugins", "extraKnownMarketplaces"] as const)
		if (config[key] !== undefined && !isRecord(config[key]))
			throw new Error(`.claude/settings.json: ${key} is not an object`);
	config.enabledPlugins = { ...config.enabledPlugins, ...Object.fromEntries(PLUGINS.map((id) => [id, true])) };
	config.extraKnownMarketplaces = { ...config.extraKnownMarketplaces, ponytail: MARKETPLACE };
	return `${JSON.stringify(config, null, indentOf(text))}\n`;
}

/** JSON's spelling of a boolean, a number and a string array is TOML's too. */
const SECTION = ["[install]", ...Object.entries(INSTALL).map(([k, v]) => `${k} = ${JSON.stringify(v)}`)];

const same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b);

function toml(text: string): Record<string, unknown> {
	try {
		return Bun.TOML.parse(text) as Record<string, unknown>;
	} catch (error) {
		throw new Error(`bunfig.toml: ${(error as Error).message}`);
	}
}

/**
 * `bunfig.toml`'s new text. An `[install]` that already equals `INSTALL` is
 * left byte for byte, so its comments survive. Otherwise its lines, up to the
 * next header, become the canonical ones. Bun parses TOML but cannot write
 * it, so that is a line scan, and the result is verified by parsing: a layout
 * the scan misreads throws rather than being written.
 */
function bunfigText(text: string | undefined): string {
	if (text === undefined) return `${SECTION.join("\n")}\n`;
	const before = toml(text);
	if (same(before.install, INSTALL)) return text;
	const lines = text.split("\n");
	const start = lines.findIndex((l) => /^\s*\[\s*install\s*\]\s*(#.*)?$/.test(l));
	let out: string[];
	if (start === -1) {
		const body = text.endsWith("\n") ? lines.slice(0, -1) : lines;
		out = [...body, ...(text.trim() ? [""] : []), ...SECTION, ""];
	} else {
		let end = lines.findIndex((l, i) => i > start && /^\s*\[/.test(l));
		if (end === -1) end = lines.length;
		while (end > start + 1 && lines[end - 1]?.trim() === "") end--;
		out = [...lines.slice(0, start), ...SECTION, ...lines.slice(end)];
	}
	const result = out.join("\n");
	const after = toml(result);
	const tables = new Set([...Object.keys(before), ...Object.keys(after)]);
	tables.delete("install");
	if (!same(after.install, INSTALL) || [...tables].some((table) => !same(before[table], after[table])))
		throw new Error(
			`bunfig.toml: replacing [install] would not leave exactly ${JSON.stringify(INSTALL)} with every other table unchanged — set it by hand`,
		);
	return result;
}

/**
 * `package.json`'s new text: `scripts.deps` added after the other scripts, or
 * the text unchanged when it already holds `DEPS`. A `deps` of the
 * consumer's own is refused, since overwriting it would break what calls it.
 */
function packageText(text: string | undefined): string {
	// JSONC, as bun reads the manifest; a comment it held is lost only when the script is added.
	const manifest = parsed("package.json", text, Bun.JSONC.parse);
	if (!isRecord(manifest)) throw new Error("package.json: not an object");
	const scripts = manifest.scripts ?? {};
	if (!isRecord(scripts)) throw new Error("package.json: scripts is not an object");
	if (scripts.deps === DEPS) return text as string;
	if (scripts.deps !== undefined)
		throw new Error(
			`package.json: scripts.deps is ${JSON.stringify(scripts.deps)}, not "${DEPS}" — rename that script, then sync`,
		);
	return `${JSON.stringify({ ...manifest, scripts: { ...scripts, deps: DEPS } }, null, indentOf(text))}${text === undefined || text.endsWith("\n") ? "\n" : ""}`;
}

type Write = readonly [file: string, was: string | undefined, now: string];

/**
 * The harness's policy for `root`'s three files, every new text computed and
 * the `bunfig.toml` one verified, so a throw comes before any write — `sync.ts`
 * calls this before it touches the rules copy too.
 */
export function settingsWrites(root: string): Write[] {
	return (
		[
			[join(root, "bunfig.toml"), bunfigText],
			[join(root, ".claude/settings.json"), settingsText],
			[join(root, "package.json"), packageText],
		] as const
	).map(([file, text]) => {
		const was = read(file);
		return [file, was, text(was)] as const;
	});
}

/** Writes each of `writes` whose text changed. */
export function applyWrites(writes: Write[]): void {
	for (const [file, was, now] of writes)
		if (was !== now) {
			mkdirSync(dirname(file), { recursive: true });
			writeFileSync(file, now);
		}
}

/** Writes the harness's policy into `root`'s three files, or none of them. */
export const syncSettings = (root: string) => applyWrites(settingsWrites(root));
